import "@mui/material/FormGroup";
export const ThemedFormGroup = {
    styleOverrides: {
        root: () => ({
            // If the parent `FormGroup` contains outlined FormControlLabels, apply 8px spacing
            // Wrapped in @supports to prevent jsdom test failures (jsdom doesn't support :has())
            "@supports selector(:has(*))": {
                "&:has(.MuiFormControlLabel-root[variant='outlined'])": {
                    gap: "8px",
                },
            },
        }),
    },
};
